# Generated by build.py from recipe.yml for recipe dns-transfer-a-whole-zone. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.surl/dns', 'closed/.surl/dns' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/dns/example.test.zone'), "`$ORIGIN example.test.`n`$TTL 300`n@    IN SOA  ns1.example.test. hostmaster.example.test. 1 3600 600 86400 300`n@    IN NS   ns1.example.test.`n@    IN MX   10 mail.example.test.`nmail IN A    192.0.2.25`nns1  IN A    192.0.2.53`n")
[IO.File]::WriteAllText((Join-Path $PWD 'closed/.surl/dns/example.test.zone'), "`$ORIGIN example.test.`n`$TTL 300`n@    IN SOA  ns1.example.test. hostmaster.example.test. 1 3600 600 86400 300`n@    IN NS   ns1.example.test.`n@    IN MX   10 mail.example.test.`nmail IN A    192.0.2.25`nns1  IN A    192.0.2.53`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-zone-transfer', 'dns://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --dns-json --dns-transport tcp "dns://127.0.0.1:8080/example.test?type=AXFR" } finally { Stop-Process $server0 }
